record.field:
if not request or not request.params:
    raise Exception("Missing request or parameters.")

csrf_token = request.params.get('token')
if not request.validate_csrf(csrf_token):
    raise Exception("Invalid CSRF token.")

image = request.params.get('image')
line_id = request.params.get('line_id')

if not image or not line_id:
    raise Exception("Missing image or line_id.")

line = env['sale.order.line'].sudo().browse(int(line_id))
if not line.exists():
    raise Exception("Sale order line not found.")

line.write({'x_custom_image': image})
